cat > $SC/extract_all.py << 'EOF'
import sys, json
path = sys.argv[1]
start_ts = sys.argv[2] if len(sys.argv) > 2 else None
end_ts = sys.argv[3] if len(sys.argv) > 3 else None
maxlen = int(sys.argv[4]) if len(sys.argv) > 4 else 500

def get_text(obj):
    msg = obj.get("message", {})
    content = msg.get("content")
    if isinstance(content, str):
        return content
    elif isinstance(content, list):
        parts = []
        for c in content:
            if not isinstance(c, dict): continue
            if c.get("type") == "text":
                parts.append(c.get("text",""))
            elif c.get("type") == "tool_use":
                parts.append(f"[tool_use:{c.get('name')}]")
            elif c.get("type") == "tool_result":
                pass
        if parts:
            return "\n".join(parts)
    return None

with open(path) as fh:
    for line in fh:
        line = line.rstrip("\n")
        try:
            obj = json.loads(line)
        except Exception:
            continue
        t = obj.get("type")
        if t not in ("user","assistant"):
            continue
        ts = obj.get("timestamp","")
        if start_ts and ts < start_ts:
            continue
        if end_ts and ts > end_ts:
            break
        text = get_text(obj)
        if not text:
            continue
        snippet = text[:maxlen].replace("\n"," | ")
        print(f"[{t}] {ts}\t{snippet}")
EOF
echo done

